/* ---------- v54: new technical films (part 2) ---------- */
const xDeLabel=(lines,x,y)=>`<g transform="translate(${x} ${y})"><rect x="-58" y="-70" width="116" height="140" rx="6" fill="#fbf3e2" stroke="#c9b28a" stroke-width="2"/><rect x="-50" y="-62" width="100" height="124" rx="3" fill="none" stroke="#d4a23a"/>${lines.map((l,i)=>fT(0,-44+i*18,l[0],l[1]||8,l[2]||"#3a2a2f","middle",l[3]||700)).join("")}</g>`;
const xDouro=()=>`<path d="M0 150Q80 120 160 140T320 128V200H0Z" fill="#3b7fa8" opacity=".9"/>${fTerraces("socalcos").replace('<path d="M0 200V60Q160 30 320 70V200Z" fill="#8a6a4a"/>','<path d="M0 200V60Q160 30 320 70V200Z" fill="#8a6a4a" opacity=".95"/>')}`;
FILMS.push(
/* ===================== TOKAJI ===================== */
{id:"tokaji",sec:"r",ch:"aut",ic:"order",nw:1,t:I3("Tokaji: l'Aszú e gli altri stili","Tokaji : l'aszú et les autres styles","Tokaji: Aszú and the other styles"),s:[
 {h:I3("Una regione fatta per la muffa nobile","Une région faite pour la pourriture noble","A region made for noble rot"),
  c:I3("Tokaj si trova nel nord-est dell'Ungheria, alla confluenza dei fiumi Bodrog e Tisza. Il clima è continentale, con autunni lunghi: le nebbie del mattino salgono dai fiumi e i pomeriggi sono caldi e asciutti. Sono le condizioni ideali per la muffa nobile. I suoli sono vulcanici, e le colline proteggono dai venti freddi del nord.",
   "Tokaj se trouve au nord-est de la Hongrie, au confluent du Bodrog et de la Tisza. Le climat est continental, avec de longs automnes : les brumes du matin montent des rivières et les après-midi sont chauds et secs. Ce sont les conditions idéales pour la pourriture noble. Les sols sont volcaniques, et les collines protègent des vents froids du nord.",
   "Tokaj lies in north-east Hungary, where the Bodrog and Tisza rivers meet. The climate is continental, with long autumns: morning mists rise from the rivers and afternoons are warm and dry. These are ideal conditions for noble rot. The soils are volcanic, and the hills shelter the vines from cold northern winds."),
  v:()=>fSvg(`${fHill("M0 150Q60 70 140 100T320 90V200H0Z","#6f8a45",fRows(30,140,280,100,14))}${fSea(0,170,320,30)}${fFog(30,150,260)}${fD(.6,fChip(90,40,"Bodrog · Tisza"))}${fD(1.2,fChip(230,40,w3("suoli vulcanici","sols volcaniques","volcanic soils")))}${fD(1.8,fChip(160,188,w3("nebbia al mattino, sole al pomeriggio","brume le matin, soleil l'après-midi","misty mornings, sunny afternoons")))}`,"autumn")},
 {h:I3("Le uve: Furmint in testa","Les cépages : le furmint en tête","The grapes: Furmint first"),
  c:I3("Il vitigno principale è il Furmint: matura tardi, ha acidità altissima e buccia sottile, sensibile alla muffa nobile. Lo affianca l'Hárslevelű, più profumato e morbido. Si usano anche il Sárgamuskotály, cioè il Moscato bianco a piccoli acini, e in piccole quantità Kabar, Kövérszőlő e Zéta.",
   "Le cépage principal est le furmint : il mûrit tard, a une acidité très élevée et une peau fine, sensible à la pourriture noble. Le hárslevelű, plus parfumé et plus souple, l'accompagne. On utilise aussi le sárgamuskotály, c'est-à-dire le muscat blanc à petits grains, et en petites quantités kabar, kövérszőlő et zéta.",
   "The main grape is Furmint: it ripens late, has very high acidity and thin skins, prone to noble rot. Alongside it is Hárslevelű, more perfumed and softer. Sárgamuskotály, that is Muscat Blanc à Petits Grains, is also used, plus small amounts of Kabar, Kövérszőlő and Zéta."),
  v:()=>fSvg(`${fD(.1,xBunch(80,70,1.5,"#c9c27a"))}${fT(80,160,"Furmint",11)}${fD(.4,fChip(80,40,w3("acidità altissima","acidité très élevée","very high acidity")))}${fD(.8,xBunch(170,78,1.2,"#d6c77a"))}${fT(170,160,"Hárslevelű",10)}${fD(1.2,xBunch(250,82,1,"#e2d58a"))}${fT(250,160,"Sárgamuskotály",8.5)}${fD(1.8,fChip(200,188,"+ Kabar · Kövérszőlő · Zéta"))}`,"autumn")},
 {h:I3("La raccolta degli acini aszú","La récolte des baies aszú","Picking the aszú berries"),
  c:I3("Gli acini colpiti dalla muffa nobile e appassiti si chiamano aszú. Si raccolgono uno a uno, a mano, con molti passaggi nel vigneto, e si conservano a parte. Le uve sane o solo in parte botritizzate dello stesso vigneto servono invece per il vino base e per gli altri stili.",
   "Les baies touchées par la pourriture noble et flétries s'appellent aszú. On les cueille une à une, à la main, en de nombreux passages dans la vigne, et on les garde à part. Les raisins sains ou seulement en partie botrytisés de la même vigne servent au vin de base et aux autres styles.",
   "Berries affected by noble rot and shrivelled are called aszú. They are picked one by one, by hand, in many passes through the vineyard, and kept separately. Healthy or only partly botrytised grapes from the same vineyard are used for the base wine and the other styles."),
  v:()=>fSvg(`${fVine("ripe")}${[0,1,2,3,4].map(i=>fD(.4+i*.3,xBotry(110+i*24,132+(i%2)*6,6))).join("")}${fD(1.6,xHod(272,170,1.4))}${fD(2,fChip(270,108,w3("acino per acino","baie par baie","berry by berry")))}${fMan(48,172,1,"#8c1d40")}`,"autumn")},
 {h:I3("Tokaji Aszú: la macerazione","Tokaji aszú : la macération","Tokaji Aszú: maceration"),
  c:I3("Gli acini aszú vengono ridotti in pasta e messi a macerare in mosto, in vino in fermentazione o in vino già fatto, per un periodo che va da dodici a sessanta ore. Così zuccheri, acidi e aromi passano nel liquido. Poi si pressa e il vino finisce la sua lenta fermentazione in botti.",
   "Les baies aszú sont réduites en pâte puis mises à macérer dans du moût, du vin en fermentation ou du vin déjà fait, pendant douze à soixante heures. Sucres, acides et arômes passent ainsi dans le liquide. Puis on presse et le vin termine sa lente fermentation en fûts.",
   "The aszú berries are crushed to a paste and steeped in must, fermenting wine or finished wine for twelve to sixty hours. Sugar, acid and flavour pass into the liquid. Then the mixture is pressed and the wine finishes its slow fermentation in casks."),
  v:()=>fSvg(`${fD(.1,xHod(60,110,1.6)+xHod(100,110,1.6))}${fD(.5,fArrow("M124 100H160",null,1))}${fTank(166,50,90,120,{col:"#d9a441",lv:.7})}${fD(.9,[0,1,2,3,4,5].map(i=>xBotry(186+i*10,128+(i%2)*8,4)).join(""))}${fD(1.4,fClock(211,36,""))}${fChip(211,186,w3("12–60 ore","12–60 heures","12–60 hours"))}`)},
 {h:I3("Dolcezza minima e puttonyos","Sucre minimal et puttonyos","Minimum sugar and puttonyos"),
  c:I3("Un tempo la dolcezza si esprimeva in puttonyos, le gerle di acini aszú aggiunte a una botte gönc da centotrentasei litri. Oggi il Tokaji Aszú deve avere almeno centoventi grammi di zucchero per litro, cioè cinque puttonyos; sei puttonyos corrispondono a centocinquanta. L'indicazione in etichetta è facoltativa.",
   "Autrefois, la douceur s'exprimait en puttonyos, les hottes de baies aszú ajoutées à un fût gönc de cent trente-six litres. Aujourd'hui le tokaji aszú doit avoir au moins cent vingt grammes de sucre par litre, soit cinq puttonyos ; six puttonyos correspondent à cent cinquante. La mention sur l'étiquette est facultative.",
   "Sweetness used to be expressed in puttonyos, the hods of aszú berries added to a 136-litre gönc cask. Today Tokaji Aszú must have at least 120 grams of sugar per litre, that is five puttonyos; six puttonyos correspond to 150. Stating them on the label is optional."),
  v:()=>fSvg(`${fBarrel(90,110,1.3)}${fT(90,154,w3("gönc 136 l","gönc 136 l","gönc 136 l"),9)}${[0,1,2,3,4].map(i=>fD(.3+i*.3,xHod(170+i*26,120,1))).join("")}${fD(2,fChip(222,64,w3("5 puttonyos ≥ 120 g/l","5 puttonyos ≥ 120 g/l","5 puttonyos ≥ 120 g/l")))}${fD(2.6,fChip(222,170,w3("6 puttonyos ≥ 150 g/l","6 puttonyos ≥ 150 g/l","6 puttonyos ≥ 150 g/l")))}`)},
 {h:I3("L'affinamento","L'élevage","Maturation"),
  c:I3("Il Tokaji Aszú deve affinare almeno diciotto mesi in botti di legno, in cantine scavate nella roccia, fresche e umide, con muffe sulle pareti. Il risultato è un vino dolcissimo ma vivo grazie all'acidità del Furmint, con aromi di albicocca, marmellata d'arancia, miele, zenzero e, con l'età, frutta secca e caffè.",
   "Le tokaji aszú doit s'élever au moins dix-huit mois en fûts de bois, dans des caves creusées dans la roche, fraîches et humides, aux murs couverts de moisissures. Le résultat est un vin très doux mais vif grâce à l'acidité du furmint, aux arômes d'abricot, de marmelade d'orange, de miel, de gingembre et, avec l'âge, de fruits secs et de café.",
   "Tokaji Aszú must age at least eighteen months in wooden casks, in cool, damp cellars carved into the rock, with mould on the walls. The result is a very sweet wine kept fresh by Furmint's acidity, with aromas of apricot, orange marmalade, honey, ginger and, with age, nuts and coffee."),
  v:()=>fSvg(`${[70,160,250].map((x,i)=>fBarrel(x,150,.95)).join("")}${[60,140,220,290].map(x=>`<circle cx="${x}" cy="${70+(x%3)*8}" r="9" fill="#3f4a32" opacity=".55"/>`).join("")}${fD(.6,fChip(160,40,w3("≥ 18 mesi in legno","≥ 18 mois en fût","≥ 18 months in cask")))}${fD(1.4,fChip(160,100,w3("albicocca · arancia · miele","abricot · orange · miel","apricot · orange · honey"),"#8c1d40"))}`)},
 {h:I3("Eszencia e Szamorodni","Eszencia et szamorodni","Eszencia and Szamorodni"),
  c:I3("L'Eszencia è il succo che cola da solo dagli acini aszú ammucchiati: è densissimo, con almeno quattrocentocinquanta grammi di zucchero per litro, e fermenta per anni arrivando a pochi gradi alcolici. Lo Szamorodni, che significa «come cresce», si fa da grappoli interi in parte botritizzati: può essere secco o dolce e affina almeno sei mesi in botte.",
   "L'eszencia est le jus qui s'écoule tout seul des baies aszú entassées : très dense, avec au moins quatre cent cinquante grammes de sucre par litre, il fermente pendant des années et n'atteint que quelques degrés d'alcool. Le szamorodni, qui signifie « tel qu'il pousse », se fait à partir de grappes entières en partie botrytisées : il peut être sec ou doux et s'élève au moins six mois en fût.",
   "Eszencia is the juice that runs freely from heaped aszú berries: very dense, with at least 450 grams of sugar per litre, it ferments for years and reaches only a few degrees of alcohol. Szamorodni, meaning 'as it grows', is made from whole bunches that are partly botrytised: it can be dry or sweet and is aged at least six months in cask."),
  v:()=>fSvg(`${[0,1,2,3,4,5,6,7].map(i=>xBotry(50+(i%4)*18,90+Math.floor(i/4)*16,7)).join("")}${fD(.5,fDrops(78,130,160,"#e8b04a",4))}${fD(.8,fGlass(80,170,"#c8862a",.7))}${fChip(80,50,"Eszencia ≥ 450 g/l")}${fD(1.4,xBunch(230,80,1.3,"#8a5a3a"))}${fD(1.8,fChip(230,50,w3("Szamorodni: secco o dolce","Szamorodni : sec ou doux","Szamorodni: dry or sweet")))}${fD(2.2,fChip(230,170,w3("≥ 6 mesi in botte","≥ 6 mois en fût","≥ 6 months in cask")))}`)},
 {h:I3("I vini secchi e vendemmia tardiva","Les vins secs et vendanges tardives","Dry wines and late harvest"),
  c:I3("Oggi Tokaj produce anche ottimi bianchi secchi da Furmint, tesi, con note di mela, agrumi e fumo, spesso affinati in legno. I vendemmia tardiva, in ungherese késői szüretelésű, sono dolci più leggeri e fruttati, fatti da uve molto mature e in parte botritizzate, senza macerazione di acini aszú.",
   "Aujourd'hui Tokaj produit aussi d'excellents blancs secs de furmint, tendus, aux notes de pomme, d'agrumes et de fumée, souvent élevés en fût. Les vendanges tardives, en hongrois késői szüretelésű, sont des vins doux plus légers et fruités, faits de raisins très mûrs et en partie botrytisés, sans macération de baies aszú.",
   "Today Tokaj also makes excellent dry whites from Furmint, taut, with apple, citrus and smoky notes, often oak-aged. Late-harvest wines, késői szüretelésű in Hungarian, are lighter, fruitier sweet wines made from very ripe, partly botrytised grapes, without macerating aszú berries."),
  v:()=>fSvg(`${fD(.1,fGlass(90,120,"#efe3a0",1.4))}${fChip(90,40,w3("Furmint secco","Furmint sec","Dry Furmint"))}${fD(.6,fGlass(230,120,"#e2b85a",1.4))}${fD(.9,fChip(230,40,w3("vendemmia tardiva","vendanges tardives","late harvest")))}${fD(1.4,fChip(160,190,w3("mela · agrumi · fumo","pomme · agrumes · fumée","apple · citrus · smoke")))}`)},
 {h:I3("Ricapitolando","En résumé","Recap"),
  c:I3("Tokaj: clima continentale con nebbie autunnali, suoli vulcanici, Furmint e Hárslevelű. Aszú: acini botritizzati raccolti uno a uno, macerati da dodici a sessanta ore, almeno centoventi grammi per litro, diciotto mesi in botte. Eszencia: succo libero, almeno quattrocentocinquanta grammi. Szamorodni: grappoli interi, secco o dolce.",
   "Tokaj : climat continental aux brumes d'automne, sols volcaniques, furmint et hárslevelű. Aszú : baies botrytisées cueillies une à une, macérées de douze à soixante heures, au moins cent vingt grammes par litre, dix-huit mois en fût. Eszencia : jus de goutte, au moins quatre cent cinquante grammes. Szamorodni : grappes entières, sec ou doux.",
   "Tokaj: continental climate with autumn mists, volcanic soils, Furmint and Hárslevelű. Aszú: botrytised berries picked one by one, steeped for 12 to 60 hours, at least 120 grams per litre, 18 months in cask. Eszencia: free-run juice, at least 450 grams. Szamorodni: whole bunches, dry or sweet."),
  v:()=>fSvg(fTable(null,[
    [I3("Tokaji Aszú","Tokaji aszú","Tokaji Aszú"),I3("≥120 g/l · ≥18 mesi","≥120 g/l · ≥18 mois","≥120 g/l · ≥18 months")],
    [I3("Eszencia","Eszencia","Eszencia"),I3("≥450 g/l · pochi gradi","≥450 g/l · peu d'alcool","≥450 g/l · low alcohol")],
    [I3("Szamorodni","Szamorodni","Szamorodni"),I3("grappoli interi · ≥6 mesi","grappes entières · ≥6 mois","whole bunches · ≥6 months")],
    [I3("Vendemmia tardiva","Vendanges tardives","Late harvest"),I3("dolce, leggero","doux, léger","sweet, lighter")],
    [I3("Furmint secco","Furmint sec","Dry Furmint"),I3("teso, minerale","tendu, minéral","taut, mineral")]],[0],{c1:130}))}
]},

/* ===================== GERMANY ===================== */
{id:"germ",sec:"r",ch:"ger",ic:"order",nw:1,t:I3("Germania: leggere un'etichetta","Allemagne : lire une étiquette","Germany: reading a label"),s:[
 {h:I3("Tredici regioni, un fiume dopo l'altro","Treize régions, de fleuve en fleuve","Thirteen regions along the rivers"),
  c:I3("La Germania ha tredici regioni vinicole, gli Anbaugebiete, quasi tutte lungo il Reno e i suoi affluenti: Mosella, Nahe, Rheingau, Rheinhessen, Pfalz, Baden e le altre. Siamo al limite nord della viticoltura: i fiumi riflettono la luce e mitigano il freddo, e i migliori vigneti sono su ripidi pendii esposti a sud.",
   "L'Allemagne compte treize régions viticoles, les Anbaugebiete, presque toutes le long du Rhin et de ses affluents : Moselle, Nahe, Rheingau, Hesse rhénane, Palatinat, Bade et les autres. On est à la limite nord de la viticulture : les fleuves reflètent la lumière et adoucissent le froid, et les meilleures vignes sont sur des pentes raides exposées au sud.",
   "Germany has thirteen wine regions, the Anbaugebiete, almost all along the Rhine and its tributaries: Mosel, Nahe, Rheingau, Rheinhessen, Pfalz, Baden and the rest. This is the northern limit of viticulture: the rivers reflect light and temper the cold, and the best vineyards are on steep south-facing slopes."),
  v:()=>fSvg(`${fHill("M0 170Q40 40 120 60Q200 80 220 170Z","#5f7d3a",fRows(20,160,190,70,16))}<path d="M0 178Q120 160 200 172T320 166V200H0Z" fill="#3b7fa8"/>${fD(.6,fRays(300,10,[[120,80],[140,100],[160,120]]))}${fD(.4,fSun(300,14,9))}${fD(1,fCall(150,90,250,60,w3("pendio ripido a sud","pente raide au sud","steep south slope")))}${fD(1.6,fCall(220,174,250,140,w3("il fiume riflette la luce","le fleuve reflète la lumière","river reflects the light")))}${fChip(80,24,w3("13 Anbaugebiete","13 Anbaugebiete","13 Anbaugebiete"))}`,"summer")},
 {h:I3("La piramide della qualità","La pyramide de la qualité","The quality pyramid"),
  c:I3("Alla base c'è il Deutscher Wein, senza indicazione geografica, poi il Landwein, che è un'IGP. Sopra ci sono le DOP: il Qualitätswein, prodotto in una delle tredici regioni, dove lo zuccheraggio è ammesso; e il Prädikatswein, il livello più alto, dove lo zuccheraggio è vietato e l'uva deve raggiungere una maturità minima.",
   "À la base se trouve le Deutscher Wein, sans indication géographique, puis le Landwein, qui est une IGP. Au-dessus viennent les AOP : le Qualitätswein, produit dans l'une des treize régions, où la chaptalisation est permise ; et le Prädikatswein, le niveau le plus élevé, où la chaptalisation est interdite et où le raisin doit atteindre une maturité minimale.",
   "At the base is Deutscher Wein, with no geographical indication, then Landwein, which is a PGI. Above are the PDOs: Qualitätswein, made in one of the thirteen regions, where chaptalisation is allowed; and Prädikatswein, the top level, where chaptalisation is banned and the grapes must reach a minimum ripeness."),
  v:()=>fSvg(`${[["Prädikatswein","#d4a23a",40],["Qualitätswein","#b06a2a",80],["Landwein (IGP)","#8a5a33",120],["Deutscher Wein","#6b4426",160]].map(([l,c,y],i)=>fD(.2+(3-i)*.35,`<path d="M${160-40-i*30} ${y-34}H${160+40+i*30}L${160+52+i*30} ${y}H${160-52-i*30}Z" fill="${c}"/>${fT(160,y-12,l,9.5,"#fff4dc")}`)).join("")}${fD(1.8,fChip(268,40,w3("niente zucchero aggiunto","pas de chaptalisation","no chaptalisation"),"#8c1d40"))}${fD(2.2,fChip(52,80,w3("DOP","AOP","PDO")))}`)},
 {h:I3("I Prädikat: la maturità dell'uva","Les Prädikat : la maturité du raisin","The Prädikate: grape ripeness"),
  c:I3("Il Prädikatswein ha sei livelli, in base alla quantità di zucchero nel mosto: Kabinett, Spätlese, Auslese, Beerenauslese, Eiswein e Trockenbeerenauslese. Attenzione: il Prädikat indica la maturità dell'uva alla raccolta, non la dolcezza del vino finito. Uno Spätlese, per esempio, può essere secco o dolce.",
   "Le Prädikatswein compte six niveaux, selon la quantité de sucre dans le moût : Kabinett, Spätlese, Auslese, Beerenauslese, Eiswein et Trockenbeerenauslese. Attention : le Prädikat indique la maturité du raisin à la récolte, pas la douceur du vin fini. Un spätlese, par exemple, peut être sec ou doux.",
   "Prädikatswein has six levels, based on the sugar content of the must: Kabinett, Spätlese, Auslese, Beerenauslese, Eiswein and Trockenbeerenauslese. Note: the Prädikat states the ripeness of the grapes at harvest, not the sweetness of the finished wine. A Spätlese, for instance, can be dry or sweet."),
  v:()=>fSvg(xLadder(["Kabinett","Spätlese","Auslese","BA","Eiswein","TBA"],-1)+fD(2,fChip(160,20,w3("maturità ≠ dolcezza","maturité ≠ douceur","ripeness ≠ sweetness"),"#8c1d40")))},
 {h:I3("Kabinett, Spätlese, Auslese","Kabinett, Spätlese, Auslese","Kabinett, Spätlese, Auslese"),
  c:I3("Il Kabinett è il più leggero: delicato, spesso con poco alcol e un tocco di dolcezza, ma esiste anche secco. Lo Spätlese è vendemmia tardiva: uve più mature, più corpo e intensità. L'Auslese viene da grappoli selezionati, molto maturi, a volte con un po' di muffa nobile: ricco, spesso dolce.",
   "Le kabinett est le plus léger : délicat, souvent peu alcoolisé avec une touche de douceur, mais il existe aussi en sec. Le spätlese est une vendange tardive : raisins plus mûrs, plus de corps et d'intensité. L'auslese provient de grappes sélectionnées, très mûres, parfois touchées par un peu de pourriture noble : riche, souvent doux.",
   "Kabinett is the lightest: delicate, often low in alcohol with a touch of sweetness, but it also comes dry. Spätlese means late harvest: riper grapes, more body and intensity. Auslese comes from selected, very ripe bunches, sometimes with a little noble rot: rich, often sweet."),
  v:()=>fSvg(xLadder(["Kabinett","Spätlese","Auslese","BA","Eiswein","TBA"],0).replace(/opacity=".85"/g,'opacity=".35"')+fD(.8,fChip(70,40,w3("leggero, poco alcol","léger, peu d'alcool","light, low alcohol")))+fD(1.4,fChip(160,60,w3("vendemmia tardiva","vendange tardive","late harvest")))+fD(2,fChip(250,30,w3("grappoli selezionati","grappes sélectionnées","selected bunches"))))},
 {h:I3("BA, Eiswein, TBA: i grandi dolci","BA, Eiswein, TBA : les grands liquoreux","BA, Eiswein, TBA: the great sweet wines"),
  c:I3("Beerenauslese significa acini selezionati: uve botritizzate o stramature, vino dolce e ricco. L'Eiswein si fa da uve congelate sulla pianta, con la stessa maturità minima del Beerenauslese ma senza muffa nobile: acidità tagliente e frutto puro. Il Trockenbeerenauslese viene da acini appassiti dalla botrite, raccolti uno a uno: è il più raro e concentrato.",
   "Beerenauslese signifie baies sélectionnées : raisins botrytisés ou surmûris, vin doux et riche. L'eiswein se fait à partir de raisins gelés sur la vigne, avec la même maturité minimale que le beerenauslese mais sans pourriture noble : acidité tranchante et fruit pur. Le trockenbeerenauslese vient de baies flétries par le botrytis, cueillies une à une : c'est le plus rare et le plus concentré.",
   "Beerenauslese means selected berries: botrytised or overripe grapes, a sweet, rich wine. Eiswein is made from grapes frozen on the vine, with the same minimum ripeness as Beerenauslese but no noble rot: piercing acidity and pure fruit. Trockenbeerenauslese comes from berries shrivelled by botrytis, picked one by one: the rarest and most concentrated."),
  v:()=>fSvg(`${fD(.1,[0,1,2].map(i=>xBotry(60+i*16,90,7)).join("")+fT(76,130,"BA",11))}${fD(.6,fCrystals(150,92,"#e6f4fb")+fT(160,130,"Eiswein",11))}${fD(1.1,[0,1,2,3].map(i=>xBotry(232+i*12,92+(i%2)*4,5)).join("")+fT(250,130,"TBA",11))}${fD(1.8,fChip(160,170,w3("dolcezza e rarità crescenti →","douceur et rareté croissantes →","rising sweetness and rarity →")))}`)},
 {h:I3("Secco o dolce? Le parole da cercare","Sec ou doux ? Les mots à chercher","Dry or sweet? The words to look for"),
  c:I3("Per capire la dolcezza bisogna leggere altre parole. Trocken significa secco; halbtrocken o feinherb indicano un vino semisecco. Se non c'è nessuna indicazione e l'alcol è basso, intorno all'otto per cento, il vino è probabilmente dolce. Un tempo si usava anche la riserva dolce, la Süssreserve, per dare dolcezza.",
   "Pour connaître la douceur, il faut lire d'autres mots. Trocken signifie sec ; halbtrocken ou feinherb indiquent un vin demi-sec. S'il n'y a aucune mention et que l'alcool est bas, autour de huit pour cent, le vin est probablement doux. On utilisait aussi la réserve douce, la Süssreserve, pour apporter de la douceur.",
   "To judge sweetness you need other words. Trocken means dry; halbtrocken or feinherb mean off-dry. If there is no statement and the alcohol is low, around eight percent, the wine is probably sweet. Sweet reserve, Süssreserve, has also been used to add sweetness."),
  v:()=>fSvg(`${fD(.1,xBox(30,46,120,30,w3("trocken = secco","trocken = sec","trocken = dry"),"rgba(94,140,49,.45)"))}${fD(.6,xBox(30,88,120,30,w3("halbtrocken · feinherb = semisecco","halbtrocken · feinherb = demi-sec","halbtrocken · feinherb = off-dry"),"rgba(212,162,58,.4)"))}${fD(1.2,xBox(30,130,120,30,w3("niente + ~8 % = dolce","rien + ~8 % = doux","nothing + ~8% = sweet"),"rgba(140,29,64,.5)"))}${fD(.3,fBottle(230,110,{col:"#efe3a0",label:1}))}${fD(.3,fChip(230,170,"Riesling"))}`)},
 {h:I3("Il VDP e i Grosses Gewächs","Le VDP et les Grosses Gewächs","The VDP and Grosses Gewächs"),
  c:I3("Il VDP è un'associazione di produttori di qualità, con una propria classificazione dei vigneti, simile alla Borgogna: Gutswein, Ortswein, Erste Lage e Grosse Lage. I vini secchi da un vigneto Grosse Lage si chiamano Grosses Gewächs, abbreviato GG. Anche la legge del 2021 ha introdotto una piramide basata sull'origine.",
   "Le VDP est une association de producteurs de qualité, avec son propre classement des vignobles, proche de la Bourgogne : Gutswein, Ortswein, Erste Lage et Grosse Lage. Les vins secs issus d'un vignoble Grosse Lage s'appellent Grosses Gewächs, en abrégé GG. La loi de 2021 a elle aussi introduit une pyramide fondée sur l'origine.",
   "The VDP is an association of quality producers with its own vineyard classification, similar to Burgundy: Gutswein, Ortswein, Erste Lage and Grosse Lage. Dry wines from a Grosse Lage vineyard are called Grosses Gewächs, abbreviated GG. The 2021 wine law also introduced an origin-based pyramid."),
  v:()=>fSvg(`${[["Grosse Lage · GG","#d4a23a",44],["Erste Lage","#b06a2a",84],["Ortswein","#8a5a33",124],["Gutswein","#6b4426",164]].map(([l,c,y],i)=>fD(.2+(3-i)*.35,`<path d="M${160-40-i*30} ${y-34}H${160+40+i*30}L${160+52+i*30} ${y}H${160-52-i*30}Z" fill="${c}"/>${fT(160,y-12,l,9.5,"#fff4dc")}`)).join("")}${fD(1.8,fChip(270,44,w3("GG = secco","GG = sec","GG = dry")))}${fChip(46,20,"VDP")}`)},
 {h:I3("Leggere un'etichetta","Lire une étiquette","Reading a label"),
  c:I3("Ecco come si legge un'etichetta tedesca tipica: il nome del produttore, la regione, ad esempio Mosel, il comune e il vigneto, il vitigno, l'annata, il livello di Prädikat e, se presente, l'indicazione di dolcezza. In questo esempio inventato: un Riesling Spätlese trocken, cioè da uve vendemmiate tardi, ma vinificato secco.",
   "Voici comment se lit une étiquette allemande typique : le nom du producteur, la région, par exemple Mosel, la commune et le vignoble, le cépage, le millésime, le niveau de Prädikat et, s'il y en a une, la mention de douceur. Dans cet exemple inventé : un riesling spätlese trocken, c'est-à-dire issu de raisins vendangés tard, mais vinifié sec.",
   "Here is how to read a typical German label: the producer's name, the region, for example Mosel, the village and vineyard, the grape, the vintage, the Prädikat level and, if present, the sweetness term. In this invented example: a Riesling Spätlese trocken, made from late-picked grapes but fermented dry."),
  v:()=>fSvg(`${xDeLabel([["WEINGUT MUSTERHOF",8.5],["Mosel",8,"#8c1d40"],["Erdener Beispiel",9],["Riesling",11],["Spätlese trocken",9.5,"#8c1d40"],["2022",9]],100,100)}${fD(.6,fCall(150,74,230,44,w3("regione","région","region")))}${fD(1,fCall(150,92,236,76,w3("comune + vigneto","commune + vignoble","village + vineyard")))}${fD(1.4,fCall(150,128,236,112,w3("Prädikat + dolcezza","Prädikat + douceur","Prädikat + sweetness")))}${fD(1.8,fChip(240,170,w3("esempio inventato","exemple inventé","invented example")))}`)},
 {h:I3("Ricapitolando","En résumé","Recap"),
  c:I3("Tredici regioni lungo i fiumi. Piramide: Deutscher Wein, Landwein, Qualitätswein, Prädikatswein. Sei Prädikat secondo la maturità dell'uva: Kabinett, Spätlese, Auslese, Beerenauslese, Eiswein, Trockenbeerenauslese. Trocken è secco, halbtrocken e feinherb semisecco. VDP: Gutswein, Ortswein, Erste Lage, Grosse Lage; il secco del Grosse Lage è il GG.",
   "Treize régions le long des fleuves. Pyramide : Deutscher Wein, Landwein, Qualitätswein, Prädikatswein. Six Prädikat selon la maturité du raisin : kabinett, spätlese, auslese, beerenauslese, eiswein, trockenbeerenauslese. Trocken signifie sec, halbtrocken et feinherb demi-sec. VDP : Gutswein, Ortswein, Erste Lage, Grosse Lage ; le sec de Grosse Lage est le GG.",
   "Thirteen regions along the rivers. Pyramid: Deutscher Wein, Landwein, Qualitätswein, Prädikatswein. Six Prädikate by grape ripeness: Kabinett, Spätlese, Auslese, Beerenauslese, Eiswein, Trockenbeerenauslese. Trocken is dry, halbtrocken and feinherb off-dry. VDP: Gutswein, Ortswein, Erste Lage, Grosse Lage; the dry Grosse Lage wine is GG."),
  v:()=>fSvg(xLadder(["Kabinett","Spätlese","Auslese","BA","Eiswein","TBA"],5))}
]},

/* ===================== SHERRY & SOLERA ===================== */
{id:"solera",sec:"s",ch:"she",ic:"order",nw:1,t:I3("Sherry: il sistema solera in dettaglio","Xérès : le système de solera en détail","Sherry: the solera system in detail"),s:[
 {h:I3("Perché un sistema solera","Pourquoi un système de solera","Why a solera"),
  c:I3("Lo Sherry non indica quasi mai l'annata. Il produttore vuole invece uno stile sempre uguale, anno dopo anno. Per questo usa la solera: un sistema di botti in cui vini di età diverse si mescolano continuamente. Così il vino in bottiglia ha sempre lo stesso carattere e un'età media che cresce nel tempo.",
   "Le xérès n'indique presque jamais de millésime. Le producteur cherche au contraire un style toujours identique, année après année. C'est pourquoi il utilise la solera : un système de fûts où des vins d'âges différents se mélangent en continu. Le vin en bouteille garde ainsi le même caractère et un âge moyen qui augmente avec le temps.",
   "Sherry almost never shows a vintage. Instead the producer wants a consistent style, year after year. That is why the solera is used: a system of casks in which wines of different ages are continuously blended. The bottled wine keeps the same character, and an average age that grows over time."),
  v:()=>fSvg(fSoleraStack(0)+fD(1.2,fChip(80,186,w3("stile costante","style constant","consistent style"))))},
 {h:I3("Le botti: butts da seicento litri","Les fûts : des butts de six cents litres","The casks: 600-litre butts"),
  c:I3("Si usano botti di rovere americano vecchio, chiamate butts, da circa seicento litri. Per i Fino e le Manzanilla si riempiono solo per cinque sesti: lo spazio vuoto lascia all'aria il contatto con la superficie del vino, dove può crescere la flor. Le botti sono vecchie proprio per non dare sapore di legno.",
   "On utilise des fûts de vieux chêne américain, appelés butts, d'environ six cents litres. Pour les finos et les manzanillas, on ne les remplit qu'aux cinq sixièmes : l'espace vide laisse l'air au contact de la surface du vin, où peut se développer le voile de flor. Les fûts sont vieux justement pour ne pas donner de goût de bois.",
   "Old American oak casks called butts, holding about 600 litres, are used. For Fino and Manzanilla they are filled only five-sixths full: the empty space leaves air in contact with the wine's surface, where flor can grow. The casks are old precisely so they give no oak flavour."),
  v:()=>fSvg(`${xButt(130,110,2.2,{flor:1})}${fD(.6,fCall(130,96,240,50,w3("spazio d'aria: 1/6","espace d'air : 1/6","air space: 1/6")))}${fD(1.2,fCall(170,104,250,96,w3("flor","voile de flor","flor")))}${fD(1.8,fCall(130,130,250,140,w3("vino: 5/6","vin : 5/6","wine: 5/6")))}${fChip(80,186,w3("rovere americano vecchio · 600 l","vieux chêne américain · 600 l","old American oak · 600 l"))}`)},
 {h:I3("La flor: un velo vivo","La flor : un voile vivant","Flor: a living veil"),
  c:I3("La flor è uno strato di lieviti che cresce sulla superficie del vino. Lo protegge dall'ossigeno, consuma glicerina e un po' di alcol, e produce acetaldeide, che dà le note di mela verde, pane e mandorla tipiche del Fino. Ha bisogno di alcol tra quindici e quindici e mezzo per cento, di umidità, freschezza e di nutrimento.",
   "La flor est une couche de levures qui se développe à la surface du vin. Elle le protège de l'oxygène, consomme de la glycérine et un peu d'alcool, et produit de l'acétaldéhyde, qui donne les notes de pomme verte, de pain et d'amande typiques du fino. Elle a besoin d'un alcool entre quinze et quinze et demi pour cent, d'humidité, de fraîcheur et de nutriments.",
   "Flor is a layer of yeast growing on the wine's surface. It protects the wine from oxygen, consumes glycerol and some alcohol, and produces acetaldehyde, which gives the green apple, bread and almond notes typical of Fino. It needs alcohol between 15 and 15.5 percent, humidity, coolness and nutrients."),
  v:()=>fSvg(`${xButt(110,110,2.4,{flor:1})}${fD(.5,fYeast(100,84)+fYeast(124,86))}${fD(1,fChip(250,40,w3("protegge dall'ossigeno","protège de l'oxygène","shields from oxygen")))}${fD(1.6,fChip(250,80,w3("glicerina ↓ · acetaldeide ↑","glycérine ↓ · acétaldéhyde ↑","glycerol ↓ · acetaldehyde ↑")))}${fD(2.2,fChip(250,120,"15–15,5 % vol"))}${fD(2.8,fChip(250,160,w3("pane · mandorla · mela","pain · amande · pomme","bread · almond · apple")))}`)},
 {h:I3("Criaderas e solera","Criaderas et solera","Criaderas and solera"),
  c:I3("Le botti sono divise in livelli. Il livello con il vino più vecchio si chiama solera; sopra ci sono le criaderas, prima, seconda, terza criadera e così via, con vini sempre più giovani. Il numero di livelli varia: spesso da tre a nove, ma per la Manzanilla possono essere molti di più.",
   "Les fûts sont répartis en niveaux. Le niveau du vin le plus vieux s'appelle solera ; au-dessus se trouvent les criaderas, première, deuxième, troisième criadera et ainsi de suite, avec des vins de plus en plus jeunes. Le nombre de niveaux varie : souvent de trois à neuf, mais pour la manzanilla il peut y en avoir bien plus.",
   "The casks are arranged in tiers. The tier with the oldest wine is called the solera; above are the criaderas, first, second, third criadera and so on, holding ever younger wines. The number of tiers varies: often three to nine, but for Manzanilla there can be many more."),
  v:()=>fSvg(fSoleraStack(0)+fD(.8,fCall(40,140,30,186,w3("la più vecchia","la plus vieille","the oldest")))+fD(1.4,fChip(260,186,w3("spesso 3–9 livelli","souvent 3 à 9 niveaux","often 3–9 tiers"))))},
 {h:I3("La saca: si preleva dalla solera","La saca : on tire de la solera","The saca: drawing from the solera"),
  c:I3("Quando serve vino da imbottigliare, si preleva una parte del vino da ogni botte della solera: è la saca. Non si svuota mai la botte: per legge si può prelevare al massimo un terzo all'anno. Il vino prelevato è un assemblaggio di tutti i vini, giovani e vecchi, che hanno attraversato il sistema.",
   "Quand il faut du vin à embouteiller, on tire une partie du vin de chaque fût de la solera : c'est la saca. On ne vide jamais le fût : la loi permet de prélever au maximum un tiers par an. Le vin tiré est un assemblage de tous les vins, jeunes et vieux, qui ont traversé le système.",
   "When wine is needed for bottling, part of the wine is drawn from every cask in the solera: this is the saca. The cask is never emptied: by law at most one third may be drawn per year. The wine drawn off is a blend of all the wines, young and old, that have passed through the system."),
  v:()=>fSvg(fSoleraStack(1)+fD(1.6,fChip(90,186,w3("massimo 1/3 all'anno","maximum 1/3 par an","at most 1/3 a year"),"#8c1d40")))},
 {h:I3("Il rocío: si rabbocca dall'alto","Le rocío : on complète par le haut","The rocío: topping up from above"),
  c:I3("Il vino tolto dalla solera viene sostituito con vino della prima criadera; quello della prima con vino della seconda, e così via fino all'ultima criadera, rabboccata con vino nuovo, il sobretabla. Questo rabbocco si chiama rocío. Il vino più giovane porta nutrimento alla flor, che così sopravvive per anni.",
   "Le vin retiré de la solera est remplacé par du vin de la première criadera ; celui de la première par du vin de la deuxième, et ainsi de suite jusqu'à la dernière criadera, complétée avec du vin nouveau, le sobretabla. Ce remplissage s'appelle rocío. Le vin plus jeune apporte des nutriments au voile de flor, qui survit ainsi des années.",
   "The wine taken from the solera is replaced with wine from the first criadera; that from the first with wine from the second, and so on up to the last criadera, topped up with new wine, the sobretabla. This topping up is called the rocío. The younger wine feeds the flor, which can survive for years."),
  v:()=>fSvg(fSoleraStack(2)+fD(3,fChip(250,186,w3("nutrimento per la flor","nutriments pour la flor","food for the flor"))))},
 {h:I3("Fino, Amontillado, Oloroso","Fino, amontillado, oloroso","Fino, Amontillado, Oloroso"),
  c:I3("Il Fino, e a Sanlúcar la Manzanilla, matura sempre sotto flor: pallido, secco, delicato. L'Amontillado inizia come Fino; poi la flor muore o il vino viene fortificato oltre il diciassette per cento e prosegue ossidativo: ambrato, nocciola. L'Oloroso è fortificato subito ad almeno diciassette per cento: niente flor, solo ossidazione, bruno, noce e toffee.",
   "Le fino, et à Sanlúcar la manzanilla, vieillit toujours sous flor : pâle, sec, délicat. L'amontillado commence comme un fino ; puis le voile meurt ou le vin est remuté au-delà de dix-sept pour cent et continue en oxydatif : ambré, noisette. L'oloroso est muté d'emblée à au moins dix-sept pour cent : pas de voile, seulement l'oxydation, brun, noix et caramel.",
   "Fino, and Manzanilla in Sanlúcar, always matures under flor: pale, dry, delicate. Amontillado starts as a Fino; then the flor dies, or the wine is fortified above 17 percent, and it continues oxidatively: amber, nutty. Oloroso is fortified straight to at least 17 percent: no flor, only oxidation, brown, walnut and toffee."),
  v:()=>fSvg(`${fD(.1,xButt(60,90,1,{flor:1,col:"#efe3a0"})+fT(60,128,"Fino",10))}${fD(.6,xButt(160,90,1,{col:"#d9a441"})+fT(160,128,"Amontillado",10))}${fD(.5,fArrow("M92 90H124",null,1))}${fD(1.2,xButt(260,90,1,{ox:1,col:"#8a4a1a"})+fT(260,128,"Oloroso",10))}${fD(1.6,fChip(60,160,"15–15,5 %"))}${fD(2,fChip(160,160,w3("flor → ossidazione","flor → oxydation","flor → oxidation")))}${fD(2.4,fChip(260,160,"≥ 17 %"))}`)},
 {h:I3("Età e indicazioni in etichetta","Âge et mentions d'étiquette","Ages and label terms"),
  c:I3("Lo Sherry deve invecchiare almeno due anni. Alcuni hanno un'indicazione d'età media: dodici o quindici anni, VOS, Very Old Sherry, per almeno vent'anni, e VORS, Very Old Rare Sherry, per almeno trenta. Esistono anche Sherry d'annata da una botte statica, detti de añada, e i Fino en rama, imbottigliati con filtrazione minima.",
   "Le xérès doit vieillir au moins deux ans. Certains portent une indication d'âge moyen : douze ou quinze ans, VOS, Very Old Sherry, pour au moins vingt ans, et VORS, Very Old Rare Sherry, pour au moins trente. Il existe aussi des xérès millésimés issus d'un fût statique, dits de añada, et des finos en rama, embouteillés avec une filtration minimale.",
   "Sherry must age at least two years. Some carry an average-age statement: twelve or fifteen years, VOS, Very Old Sherry, for at least twenty years, and VORS, Very Old Rare Sherry, for at least thirty. There are also vintage sherries from a static cask, called de añada, and en rama Finos, bottled with minimal filtration."),
  v:()=>fSvg(fTable(null,[[I3("minimo","minimum","minimum"),I3("2 anni","2 ans","2 years")],[I3("12 · 15 anni","12 · 15 ans","12 · 15 years"),I3("età media","âge moyen","average age")],["VOS",I3("≥ 20 anni","≥ 20 ans","≥ 20 years")],["VORS",I3("≥ 30 anni","≥ 30 ans","≥ 30 years")],[I3("de añada","de añada","de añada"),I3("annata, botte statica","millésime, fût statique","vintage, static cask")],["en rama",I3("filtrazione minima","filtration minimale","minimal filtration")]],[2,3],{c1:120}))},
 {h:I3("Ricapitolando","En résumé","Recap"),
  c:I3("Butts vecchi da seicento litri, riempiti a cinque sesti per la flor. Solera in basso, criaderas sopra. Saca: al massimo un terzo all'anno dalla solera. Rocío: ogni livello rabbocca quello sotto, l'ultimo riceve il vino nuovo. Fino sotto flor, Amontillado prima flor poi ossidazione, Oloroso solo ossidazione.",
   "Vieux butts de six cents litres, remplis aux cinq sixièmes pour la flor. Solera en bas, criaderas au-dessus. Saca : au maximum un tiers par an de la solera. Rocío : chaque niveau complète celui du dessous, le dernier reçoit le vin nouveau. Fino sous flor, amontillado d'abord sous flor puis oxydatif, oloroso seulement oxydatif.",
   "Old 600-litre butts, filled five-sixths full for the flor. Solera at the bottom, criaderas above. Saca: at most one third a year from the solera. Rocío: each tier tops up the one below, the last receives new wine. Fino under flor, Amontillado first under flor then oxidative, Oloroso oxidative only."),
  v:()=>fSvg(fFlow([{t:I3("vino nuovo (sobretabla)","vin nouveau (sobretabla)","new wine (sobretabla)"),io:1},I3("criaderas","criaderas","criaderas"),"solera",{t:I3("saca ≤ 1/3 → bottiglia","saca ≤ 1/3 → bouteille","saca ≤ 1/3 → bottle"),io:1}],2,{per:4,stag:1,bh:46,y0:70}))}
]},

/* ===================== PORT STYLES ===================== */
{id:"portst",sec:"s",ch:"prt",ic:"order",nw:1,t:I3("Porto: dalla fortificazione agli stili","Porto : du mutage aux styles","Port: from fortification to styles"),s:[
 {h:I3("Una fermentazione di due giorni","Une fermentation de deux jours","A two-day fermentation"),
  c:I3("Per il Porto bisogna estrarre colore, tannino e aromi in pochissimo tempo, perché la fermentazione dura solo un paio di giorni. Per questo l'estrazione è molto energica: pigiatura con i piedi nei lagares, pistoni robotici o autovinificatori. Quando l'alcol arriva a circa sei-nove per cento, si ferma tutto.",
   "Pour le porto, il faut extraire couleur, tanin et arômes en très peu de temps, car la fermentation ne dure que deux jours environ. L'extraction est donc très énergique : foulage aux pieds dans les lagares, pistons robotisés ou autovinificateurs. Quand l'alcool atteint environ six à neuf pour cent, on arrête tout.",
   "For Port, colour, tannin and flavour must be extracted very quickly, because fermentation lasts only a couple of days. So extraction is vigorous: foot treading in lagares, robotic pistons or autovinifiers. When the alcohol reaches about six to nine percent, everything stops."),
  v:()=>fSvg(`${fLagar(160,150)}${fD(.6,fClock(60,40,""))}${fChip(60,72,w3("≈ 2 giorni","≈ 2 jours","≈ 2 days"))}${fD(1.2,fChip(250,40,w3("stop a 6–9 % vol","arrêt à 6–9 % vol","stop at 6–9% abv"),"#8c1d40"))}`)},
 {h:I3("La fortificazione","Le mutage","Fortification"),
  c:I3("Il vino in fermentazione, ancora dolce, viene separato dalle bucce e mescolato con aguardente, un'acquavite d'uva a circa settantasette per cento. Le proporzioni tipiche: circa un litro di acquavite ogni quattro di vino, cioè centoquindici litri per una pipa da cinquecentocinquanta. I lieviti muoiono e il Porto resta dolce, tra diciannove e ventidue gradi.",
   "Le vin en fermentation, encore doux, est séparé des peaux et mélangé avec de l'aguardente, une eau-de-vie de raisin à environ soixante-dix-sept pour cent. Proportions typiques : environ un litre d'eau-de-vie pour quatre de vin, soit cent quinze litres pour une pipe de cinq cent cinquante. Les levures meurent et le porto reste doux, entre dix-neuf et vingt-deux degrés.",
   "The fermenting, still-sweet wine is drawn off the skins and mixed with aguardente, a grape spirit of about 77 percent. Typical proportions: roughly one litre of spirit to four of wine, that is 115 litres in a 550-litre pipe. The yeast dies and Port stays sweet, at nineteen to twenty-two percent."),
  v:()=>fSvg(`${fTank(40,60,80,110,{col:"#5a0f24",lv:.7,bub:6})}${xStill(170,150)}${fD(.6,`<path d="M120 120H220" stroke="#f3e8c8" stroke-width="0"/>`)}${fD(.8,fArrow("M120 130C150 150 190 150 220 132",null,1))}${fD(.9,fArrow("M200 110C210 116 214 122 220 128",null,1))}${fBarrel(262,130,1.1)}${fChip(80,44,w3("4 parti di vino","4 parts de vin","4 parts wine"))}${fD(.4,fChip(170,74,w3("1 parte · 77 %","1 part · 77 %","1 part · 77%")))}${fD(1.6,fChip(262,178,w3("pipa 550 l · 19–22 %","pipe 550 l · 19–22 %","pipe 550 l · 19–22%")))}`)},
 {h:I3("Dove matura: Douro o Gaia","Où il vieillit : Douro ou Gaia","Where it matures: Douro or Gaia"),
  c:I3("Per secoli il Porto è stato portato a Vila Nova de Gaia, alla foce del Douro, dove il clima atlantico, fresco e umido, rallenta l'evoluzione. Dal millenovecentottantasei può affinare anche nel Douro, più caldo e secco: lì il vino evolve più in fretta e può prendere note più cotte, il cosiddetto «Douro bake».",
   "Pendant des siècles, le porto a été transporté à Vila Nova de Gaia, à l'embouchure du Douro, où le climat atlantique, frais et humide, ralentit l'évolution. Depuis mil neuf cent quatre-vingt-six, il peut aussi vieillir dans le Douro, plus chaud et plus sec : le vin y évolue plus vite et peut prendre des notes plus cuites, le fameux « Douro bake ».",
   "For centuries Port was shipped to Vila Nova de Gaia, at the mouth of the Douro, where the cool, damp Atlantic climate slows its evolution. Since 1986 it may also be aged in the Douro, which is hotter and drier: there the wine evolves faster and can pick up more baked notes, the so-called 'Douro bake'."),
  v:()=>fSvg(`${xDouro()}${fD(.5,fChip(70,40,w3("Douro: caldo, secco","Douro : chaud, sec","Douro: hot, dry"),"#8c1d40"))}${fD(1,fChip(250,40,w3("Gaia: fresco, umido","Gaia : frais, humide","Gaia: cool, damp")))}${fD(1.6,fCurrent("M60 168Q160 150 280 160","#bfe3f5"))}${fD(2,fChip(160,188,w3("dal 1986 anche nel Douro","depuis 1986 aussi dans le Douro","since 1986 also in the Douro")))}`,"summer")},
 {h:I3("Due famiglie: ruby e tawny","Deux familles : ruby et tawny","Two families: ruby and tawny"),
  c:I3("Gli stili ruby affinano in grandi recipienti, con poco ossigeno: conservano colore profondo e frutto rosso e nero. Gli stili tawny affinano a lungo in piccole pipe di legno, con molto ossigeno: il colore diventa ambrato, il frutto si trasforma in frutta secca, noce, caramello e caffè.",
   "Les styles ruby vieillissent dans de grands contenants, avec peu d'oxygène : ils gardent une couleur profonde et un fruit rouge et noir. Les styles tawny vieillissent longtemps dans de petites pipes en bois, avec beaucoup d'oxygène : la couleur devient ambrée, le fruit se transforme en fruits secs, noix, caramel et café.",
   "Ruby styles age in large vessels with little oxygen: they keep a deep colour and red and black fruit. Tawny styles age for a long time in small wooden pipes with plenty of oxygen: the colour turns amber and the fruit becomes dried fruit, walnut, caramel and coffee."),
  v:()=>fSvg(`${fD(.1,`<rect x="30" y="50" width="100" height="110" rx="8" fill="url(#fwood)" stroke="#4e321c"/>`+fT(80,176,w3("grande botte: ruby","grand foudre : ruby","large vat: ruby"),8.5))}${fD(.4,fGlass(80,110,"#5a0a20",1.1))}${fD(1,fBarrel(220,100,1.1,{cut:1,col:"#b5651d",ox:1}))}${fD(1.3,fT(220,176,w3("piccola pipa: tawny","petite pipe : tawny","small pipe: tawny"),8.5))}`)},
 {h:I3("Ruby, Reserve e Late Bottled Vintage","Ruby, reserve et late bottled vintage","Ruby, Reserve and Late Bottled Vintage"),
  c:I3("Il Ruby base è giovane e fruttato, affinato un paio d'anni. Il Reserve Ruby è più concentrato e affina più a lungo. Il Late Bottled Vintage viene da una sola annata e si imbottiglia tra il quarto e il sesto anno dopo la vendemmia: più morbido e pronto del Vintage, di solito filtrato, quindi non va decantato.",
   "Le ruby de base est jeune et fruité, élevé environ deux ans. Le reserve ruby est plus concentré et vieillit plus longtemps. Le late bottled vintage provient d'une seule année et se met en bouteille entre la quatrième et la sixième année après la vendange : plus souple et prêt que le vintage, en général filtré, il ne se décante donc pas.",
   "Basic Ruby is young and fruity, aged a couple of years. Reserve Ruby is more concentrated and aged longer. Late Bottled Vintage comes from a single year and is bottled four to six years after the harvest: softer and readier than Vintage, usually filtered, so it does not need decanting."),
  v:()=>fSvg(xPortBottles(["#5a0a20","#4a0818","#3d0716"],[I3("Ruby","Ruby","Ruby"),I3("Reserve Ruby","Reserve ruby","Reserve Ruby"),I3("LBV: 4–6 anni","LBV : 4–6 ans","LBV: 4–6 years")]))},
 {h:I3("Vintage e Single Quinta","Vintage et single quinta","Vintage and Single Quinta"),
  c:I3("Il Porto Vintage si fa solo nelle annate migliori, dichiarate dai produttori. Si imbottiglia dopo due o tre anni, senza filtrazione, e poi evolve in bottiglia per decenni, formando un deposito: va decantato. Nelle annate non dichiarate, alcune case producono un Single Quinta Vintage da una sola tenuta.",
   "Le porto vintage ne se fait que les meilleures années, déclarées par les producteurs. Il est mis en bouteille après deux ou trois ans, sans filtration, puis évolue en bouteille pendant des décennies en formant un dépôt : il faut le décanter. Les années non déclarées, certaines maisons produisent un single quinta vintage issu d'un seul domaine.",
   "Vintage Port is made only in the best years, declared by the producers. It is bottled after two or three years, unfiltered, then evolves in bottle for decades, throwing a deposit: it must be decanted. In undeclared years, some houses make a Single Quinta Vintage from a single estate."),
  v:()=>fSvg(`${fBottle(80,110,{col:"#2a0410",cork:1,label:1,lees:1})}${fD(.6,fCall(80,140,150,160,w3("deposito","dépôt","deposit")))}${fD(1,fChip(80,40,w3("2–3 anni in botte, poi decenni","2–3 ans en fût, puis des décennies","2–3 years in cask, then decades")))}${fD(1.5,fDecanter(220,140,"#3d0716"))}${fD(1.8,fCandle(268,150))}${fD(2.2,fChip(230,40,w3("decantare","décanter","decant")))}`)},
 {h:I3("Tawny con indicazione d'età e Colheita","Tawny avec indication d'âge et colheita","Aged Tawny and Colheita"),
  c:I3("I Tawny con indicazione d'età, dieci, venti, trenta o oltre quarant'anni, sono assemblaggi che hanno il carattere di quell'età media. Il Colheita è un tawny di una sola annata, affinato almeno sette anni in legno. Sono pronti da bere quando escono e non migliorano in bottiglia.",
   "Les tawnies avec indication d'âge, dix, vingt, trente ou plus de quarante ans, sont des assemblages qui ont le caractère de cet âge moyen. Le colheita est un tawny d'une seule année, élevé au moins sept ans en fût. Ils sont prêts à boire à leur sortie et ne s'améliorent pas en bouteille.",
   "Tawnies with an indication of age, ten, twenty, thirty or over forty years, are blends showing the character of that average age. Colheita is a single-vintage tawny aged at least seven years in wood. They are ready to drink when released and do not improve in bottle."),
  v:()=>fSvg(xPortBottles(["#9a4a1a","#8a3a12","#7a3010","#6a2a0e"],["10","20","30","40+"])+fD(1.6,fChip(160,30,w3("Colheita: 1 annata, ≥ 7 anni in legno","Colheita : 1 année, ≥ 7 ans en fût","Colheita: 1 vintage, ≥ 7 years in wood"))))},
 {h:I3("Bianco e rosato","Blanc et rosé","White and rosé"),
  c:I3("Esistono anche Porti bianchi, da uve bianche: da secchi a dolci, spesso serviti con acqua tonica, oppure invecchiati a lungo in legno come i tawny. E il Porto rosato, ottenuto con una macerazione breve e servito fresco, giovane e fruttato.",
   "Il existe aussi des portos blancs, de raisins blancs : de secs à doux, souvent servis avec du tonic, ou vieillis longtemps en fût comme les tawnies. Et le porto rosé, obtenu par une courte macération et servi frais, jeune et fruité.",
   "There are also white Ports, from white grapes: from dry to sweet, often served with tonic, or long aged in wood like tawnies. And rosé Port, made with a short maceration and served chilled, young and fruity."),
  v:()=>fSvg(`${fD(.1,fGlass(100,120,"#efe0a0",1.4))}${fT(100,174,w3("Porto bianco","Porto blanc","White Port"),9)}${fD(.5,fGlass(220,120,"#ef9aa0",1.4))}${fT(220,174,w3("Porto rosato","Porto rosé","Rosé Port"),9)}`,"summer")},
 {h:I3("Ricapitolando","En résumé","Recap"),
  c:I3("Fermentazione breve e molto estrattiva, fermata a sei-nove per cento con aguardente a settantasette per cento, un litro ogni quattro: Porto dolce a diciannove-ventidue gradi. Ruby in grandi recipienti: Ruby, Reserve, LBV, Vintage da decantare. Tawny in piccole pipe: età media dieci, venti, trenta, oltre quaranta, e Colheita d'annata.",
   "Fermentation courte et très extractive, arrêtée à six-neuf pour cent avec une aguardente à soixante-dix-sept pour cent, un litre pour quatre : porto doux à dix-neuf-vingt-deux degrés. Ruby en grands contenants : ruby, reserve, LBV, vintage à décanter. Tawny en petites pipes : âge moyen dix, vingt, trente, plus de quarante, et colheita millésimé.",
   "Short, highly extractive fermentation, stopped at six to nine percent with 77-percent aguardente, one litre to four: sweet Port at 19 to 22 percent. Ruby in large vessels: Ruby, Reserve, LBV, Vintage to decant. Tawny in small pipes: average ages ten, twenty, thirty, over forty, and single-vintage Colheita."),
  v:()=>fSvg(fTable(null,[[I3("Ruby / Reserve","Ruby / reserve","Ruby / Reserve"),I3("grandi botti, fruttato","grands foudres, fruité","large vats, fruity")],["LBV",I3("1 annata, 4–6 anni","1 année, 4–6 ans","1 year, 4–6 years")],["Vintage",I3("annata dichiarata, decantare","année déclarée, décanter","declared year, decant")],["Tawny 10/20/30/40",I3("piccole pipe, età media","petites pipes, âge moyen","small pipes, average age")],["Colheita",I3("1 annata, ≥ 7 anni","1 année, ≥ 7 ans","1 year, ≥ 7 years")]],[2],{c1:130}))}
]}
);
/* film list with the new "Regions & appellations" section and New badges */
FSEC.r=I3("Regioni e denominazioni","Régions et appellations","Regions and appellations");
function renderFilms(){ const seen=flSeen(); let n=0;
  return `<section class="view films"><p class="flintro">${t("flIntro")}</p>${["v","c","r","s","t"].map(sec=>{ const L_=FILMS.map((f,i)=>[f,i]).filter(([f])=>f.sec===sec); if(!L_.length) return "";
    return `<h2 class="hsec">${esc(tx(FSEC[sec]))}</h2><div class="flgrid">${L_.map(([f,i])=>`<button type="button" class="flcard" data-film="${i}"><span class="flthumb">${f.s[0].v()}<span class="flplay">▶</span><span class="flnum">${++n}</span>${f.nw&&!seen[f.id]?`<span class="flnew">${esc(t("ytNew"))}</span>`:""}</span><span class="fltx"><b>${esc(tx(f.t))}</b><span>${f.s.length} ${t("flScenes")}${seen[f.id]?` · ✓ ${t("flSeen")}`:""}</span></span></button>`).join("")}</div>`; }).join("")}</section>`; }
try{ const st=document.createElement("style"); st.textContent=`.flnew{position:absolute;right:8px;top:8px;background:#e0263f;color:#fff;font-size:.68rem;font-weight:800;padding:2px 8px;border-radius:999px;letter-spacing:.04em;text-transform:uppercase}`; document.head.appendChild(st); }catch(e){}
